package org.apache.commons.lang3.text.translate;

import java.io.*;
import java.io.IOException;
import java.io.StringWriter;
import java.io.Writer;
import java.math.*;
import java.util.*;
import java.util.Locale;
import org.apache.commons.lang3.text.translate.CharSequenceTranslator;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;

/**
 * Unit tests for CharSequenceTranslator.with(CharSequenceTranslator... translators)
 */
public class CharSequenceTranslator_with_TriageGen0Test {

    /**
     * Mock implementation of CharSequenceTranslator to verify aggregation logic.
     */
    private static class MockTranslator extends CharSequenceTranslator {
        private final String replacement;

        MockTranslator(String replacement) {
            this.replacement = replacement;
        }

        @Override
        public int translate(CharSequence input, int index, StringWriter out) throws IOException {
            out.write(replacement);
            return input.length(); // Return length to simulate consumption
        }

        @Override
        public int translate(CharSequence input, int index, java.io.Writer out) throws IOException {
            out.write(replacement);
            return input.length();
        }
    }

    @Test
    public void testWith_NoAdditionalTranslators() throws IOException {
        // Arrange
        CharSequenceTranslator base = new MockTranslator("BASE");
        String input = "test";

        // Act
        CharSequenceTranslator result = base.with();

        // Assert
        assertNotNull(result);
        StringWriter out = new StringWriter();
        // The implementation adds the current translator at index 0 and then appends new ones.
        // With 0 additional, it creates an AggregateTranslator with [base].
        result.translate(input, out);
        assertEquals("BASE", out.toString());
    }

    @Test
    public void testWith_SingleAdditionalTranslator() throws IOException {
        // Arrange
        CharSequenceTranslator base = new MockTranslator("BASE");
        CharSequenceTranslator extra = new MockTranslator("EXTRA");
        String input = "test";

        // Act
        CharSequenceTranslator result = base.with(extra);

        // Assert
        assertNotNull(result);
        StringWriter out = new StringWriter();
        // Expected order: base then extra
        result.translate(input, out);
        assertEquals("BASEEXTRA", out.toString());
    }

    @Test
    public void testWith_MultipleAdditionalTranslators() throws IOException {
        // Arrange
        CharSequenceTranslator base = new MockTranslator("BASE");
        CharSequenceTranslator t1 = new MockTranslator("1");
        CharSequenceTranslator t2 = new MockTranslator("2");
        CharSequenceTranslator t3 = new MockTranslator("3");
        String input = "test";

        // Act
        CharSequenceTranslator result = base.with(t1, t2, t3);

        // Assert
        assertNotNull(result);
        StringWriter out = new StringWriter();
        // Expected order: base, 1, 2, 3
        result.translate(input, out);
        assertEquals("BASE123", out.toString());
    }

    @Test
    public void testWith_MaintainsOrderAndIntegrity() throws IOException {
        // Arrange
        // Use a real translator logic if possible, but Mock is sufficient for coverage of the 'with' method
        CharSequenceTranslator base = new CharSequenceTranslator() {
            @Override
            public int translate(CharSequence input, int index, java.io.Writer out) throws IOException {
                out.write("B");
                return 1;
            }
        };

        CharSequenceTranslator t1 = new CharSequenceTranslator() {
            @Override
            public int translate(CharSequence input, int index, java.io.Writer out) throws IOException {
                out.write("1");
                return 1;
            }
        };

        // Act
        CharSequenceTranslator result = base.with(t1);

        // Assert
        StringWriter out = new StringWriter();
        result.translate("X", out);
        assertEquals("B1", out.toString());
    }
}
